window.OL_I18N = {"lang":"pt-BR","dict":{"meta.appName":"Verificador de compatibilidade com eSIM da Openline","meta.searchTitle":"Compatibilidade de {q} com eSIM · Openline","ui.skip":"Pular para o conteúdo","ui.brandAria":"Openline — Verifique se seu aparelho é compatível","ui.brandSub":"Verifique se seu aparelho é compatível","lang.label":"Idioma","lang.aria":"Alterar idioma","hero.titleHtml":"Seu aparelho aceita <span class=\"accent\">eSIM</span>?","hero.tag":"Celular, tablet, smartwatch, roteador — digite qualquer marca ou modelo e descubra em um segundo se a Openline pode ser ativada nele.","search.placeholder":"Tente “iPhone 18 Pro”, “Galaxy Z Fold8”, “Pixel Watch 5”, “iPad Air” ou o código do modelo…","search.aria":"Buscar por marca, modelo ou código do aparelho","search.clear":"Limpar busca","stats.devices":"aparelhos","stats.compatible":"compatíveis","stats.notCompatible":"incompatíveis","stats.brands":"marcas","filters.label":"Filtros","filters.summaryAll":"Todos os aparelhos · Todas as marcas","filters.explain":"Escolha um status de compatibilidade e/ou uma ou mais marcas. Os filtros se combinam com a busca e atualizam a lista abaixo em tempo real.","filters.compat":"Compatibilidade","filters.compatAria":"Filtros de compatibilidade","filters.brands":"Marcas","filters.brandsAria":"Filtros de marca","filters.clearAll":"Limpar tudo","filters.compatOnly":"Apenas compatíveis","filters.notCompatOnly":"Apenas incompatíveis","filters.allStatuses":"Todos os status","filters.nBrands":{"many":"{n} de marcas","one":"{n} marca","other":"{n} marcas"},"filters.matchHtml":{"many":"<strong>{n}</strong> de aparelhos encontrados","one":"<strong>{n}</strong> aparelho encontrado","other":"<strong>{n}</strong> aparelhos encontrados"},"cat.count":{"many":"{n} de aparelhos","one":"{n} aparelho","other":"{n} aparelhos"},"results.all":"Todos os aparelhos","results.matching":"Aparelhos encontrados","results.ofTotalHtml":"<strong>{n}</strong> de {total}","results.totalHtml":"<strong>{n}</strong> no total","results.showingFirst":" · mostrando os primeiros {max}","legend.ok":"Aceita eSIM","legend.err":"Apenas chip físico","status.ok":"Compatível","status.no":"Incompatível","status.okAria":"Compatível com eSIM","status.noAria":"Incompatível com eSIM","note.caveatAria":"Ressalva regional: {note}","popover.aria":"Ressalva regional","popover.close":"Fechar","empty.noMatchTitle":"Nenhum resultado exato.","empty.noMatchBodyHtml":"Tente buscar apenas a marca (ex.: <em>Samsung</em>) ou o código exato do modelo (ex.: <em>SM-S921B</em>). Se o seu aparelho foi lançado depois de 2021 e vendido fora da China continental, a chance de aceitar eSIM é muito alta.","empty.bothTitle":"Nenhum aparelho corresponde à sua busca e aos filtros.","empty.bothBodyHtml":{"many":"Sua busca por <em>{q}</em> encontrou <strong>{n}</strong> de aparelhos no total, mas nenhum atende aos filtros atuais. Será que os filtros estão causando o conflito?","one":"Sua busca por <em>{q}</em> encontrou <strong>{n}</strong> aparelho no total, mas ele não atende aos filtros atuais. Será que os filtros estão causando o conflito?","other":"Sua busca por <em>{q}</em> encontrou <strong>{n}</strong> aparelhos no total, mas nenhum atende aos filtros atuais. Será que os filtros estão causando o conflito?"},"empty.filtersTitle":"Nenhum aparelho corresponde aos seus filtros.","empty.filtersBody":"Tente flexibilizar os filtros — combinar status raros com marcas específicas pode não deixar nenhum resultado.","empty.nothing":"Nada por aqui ainda.","empty.resetFilters":"Redefinir filtros","empty.clearSearch":"Limpar busca","footer.privacy":"Privacidade","footer.terms":"Termos","footer.socialAria":"Openline nas redes sociais","footer.onNetwork":"Openline no {network}","footer.handleOnNetwork":"@askopenline no {network}","footer.indexedHtml":"<b id=\"footer-total\">{n}</b> aparelhos indexados","region.US":"Estados Unidos","region.HK":"Hong Kong","region.CN":"China continental","region.KR":"Coreia do Sul","region.JP":"Japão","region.AU":"Austrália","region.TW":"Taiwan","region.SEA":"Sudeste Asiático","region.EU":"União Europeia","region.IN":"Índia","region.UK":"Reino Unido","exp.carrierWatch":"Smartwatches com rede celular recebem o eSIM por um plano de relógio da operadora, configurado pelo app complementar no celular pareado (app Apple Watch, Galaxy Wearable, app Pixel Watch). Os códigos QR de eSIM de celular ou de viagem não podem ser instalados diretamente no relógio; verifique se sua operadora oferece um plano para este relógio.","exp.gpsOnly":"Esta é a versão somente GPS. Ela não tem modem celular e, por isso, não aceita nenhum eSIM. A versão GPS + Cellular do mesmo relógio tem um código de modelo diferente.","exp.cnHkMoDualNano":"Os iPhones desta geração vendidos na China continental, Hong Kong e Macau têm duas bandejas para nano-SIM físico e não têm eSIM. A Openline não pode ser instalada nesses aparelhos. Confira o código do modelo em Ajustes › Geral › Sobre.","exp.cnDualNano":"A versão deste celular vendida na China continental usa dois nano-SIMs físicos e não tem eSIM. Os modelos vendidos em outros lugares aceitam eSIM. Confira o código do modelo em Ajustes › Geral › Sobre.","exp.cnLocalRules":"A versão da China continental aceita eSIM, mas as operadoras chinesas só ativam eSIM em suas lojas, com verificação de identidade, e perfis de eSIM estrangeiros não podem ser instalados enquanto você estiver na China continental. Fora da China, eSIMs de viagem como o da Openline são instalados normalmente.","exp.esimOnlyUsJpCaGulf":"Unidades vendidas nos Estados Unidos, Canadá, Japão, México e países do Golfo não têm bandeja de SIM e funcionam apenas com eSIM. Nos demais lugares, o celular também tem bandeja para nano-SIM, e unidades da China continental podem não ter eSIM. A Openline funciona em qualquer versão compatível com eSIM.","exp.noSimTray":"Esta versão não tem bandeja de SIM físico: todas as linhas, incluindo a Openline, são adicionadas como eSIM. Você pode guardar vários eSIMs e alternar entre eles nas Configurações.","exp.iden":"Este aparelho funciona na rede iDEN da Motorola (push-to-talk da Nextel / Boost), totalmente desativada pela Sprint em junho de 2013. Ele não consegue se conectar a nenhuma rede celular moderna, com eSIM ou sem. Apenas item de museu/colecionador.","exp.cdmaVerizon":"Este é um aparelho somente CDMA, feito para a antiga rede CDMA 2G/3G da Verizon, desativada em 31 de dezembro de 2022. Ele não tem nenhum compartimento de SIM (físico ou eSIM) — o CDMA autentica o aparelho na rede pelo ESN/MEID, não por um SIM. Não pode ser usado com a Openline nem com nenhuma operadora moderna.","exp.cdmaSprint":"Este é um aparelho CDMA feito para a antiga rede da Sprint, que a T-Mobile desativou definitivamente em 31 de maio de 2022. Modelos mais novos da Sprint ganharam LTE/GSM, mas os anteriores são somente CDMA e não se conectam a nenhuma rede moderna — com ou sem eSIM.","exp.sunset":"Este aparelho depende de redes 3G ou 4G antigas que as operadoras desativaram (3G da AT&T encerrado em fevereiro de 2022, T-Mobile em fevereiro de 2022, Verizon em dezembro de 2022, a maior parte do 3G europeu até 2025). Mesmo que tenha entrada de SIM funcionando, não há rede para ele se conectar na maioria dos países.","exp.windowsPhone":"Este aparelho roda Windows Phone (ou Windows 10 Mobile), descontinuado pela Microsoft em 2019 — a Loja, as atualizações de segurança e a maioria dos serviços da própria Microsoft foram encerrados. Não tem hardware de eSIM e praticamente não há suporte a aplicativos atuais. Inviável para uso diário.","exp.kaios":"Este é um celular básico com KaiOS. Quase nenhum aparelho KaiOS aceita eSIM — eles usam SIM físico (geralmente nano-SIM) e são voltados a mercados de celulares básicos 4G baratos, como Índia (JioPhone) e África. A Openline não pode ser instalada aqui.","exp.telematics":"Este é um módulo de telemática veicular (Tesla, BMW, Audi etc.) com eSIM embarcado de fábrica, soldado na placa de conectividade do veículo. O eSIM é provisionado pela montadora na fábrica e não pode ser trocado por um perfil instalado pelo usuário, como o da Openline. Não pode ser reparado pelo usuário.","exp.satellite":"Este é um comunicador via satélite/GPS (Garmin inReach, SPOT, Zoleo, Iridium GO) que usa a rede de satélites Iridium ou Globalstar — não a rede celular GSM/LTE. Ele não pode usar eSIM no sentido convencional; a conectividade está vinculada a uma assinatura proprietária com o fabricante do rastreador.","exp.medical":"Este é um dispositivo de alerta médico ou PERS (resposta a emergências pessoais). Seu modem celular é bloqueado para o provedor do serviço (Lively, Medical Guardian, Life Alert, Bay Alarm) e só funciona com a assinatura de monitoramento deles. Não aceita eSIMs de terceiros.","exp.rugged":"Este é um aparelho Samsung Enterprise / Rugged (linha Galaxy XCover) para equipes de campo — armazéns, saúde, hotelaria. Ele aceita eSIM, mas a ativação pode passar pela configuração de MDM Samsung Knox da sua empresa. A Openline é instalada como em qualquer celular comum, se o aparelho estiver desbloqueado.","exp.harmony":"Este aparelho roda HarmonyOS (Huawei) sem Google Mobile Services. A ativação do eSIM normalmente exige o app de serviços de operadora do EMUI/HarmonyOS da Huawei; os perfis da Openline são provisionados pelo código QR, mas ativações baseadas no Google Wallet não funcionam. Aparelhos vendidos na China continental também podem rejeitar perfis de eSIM internacionais por restrições do firmware CN.","exp.dualEsimOnly":"Esta variante aceita dois eSIMs simultaneamente, mas não tem bandeja de SIM físico. A Openline funciona — só não é possível combiná-la com um nano-SIM. Em algumas versões regionais, apenas um eSIM pode ficar ativo por vez.","exp.euCarrier":"Algumas variantes deste aparelho bloqueadas por operadoras europeias foram lançadas com o eSIM desativado no firmware. Modelos desbloqueados/globais aceitam eSIM normalmente. Fale com a operadora original se a ativação falhar.","exp.usCarrier":"Esta é uma variante de operadora dos EUA (AT&T, T-Mobile, Verizon, Sprint), com firmware bloqueado e, muitas vezes, suporte a bandas específicas da operadora. O eSIM pode estar desativado ou restrito aos perfis da operadora da marca. Unidades internacionais desbloqueadas do mesmo modelo costumam funcionar com a Openline; as de operadora podem não funcionar.","exp.verizon":"As unidades deste Pixel da Verizon tiveram o eSIM desativado no lançamento na rede da Verizon. Unidades desbloqueadas e de outras operadoras aceitam eSIM normalmente.","exp.googleFi":"Nesta geração do Pixel, o eSIM só estava disponível pelo Google Fi nos EUA. Outras operadoras usavam apenas SIM físico. Unidades globais desbloqueadas aceitam eSIM em qualquer lugar.","exp.usEsimOnly":"Nas unidades deste iPhone compradas nos EUA, a Apple removeu totalmente a bandeja de SIM físico — é preciso usar eSIM. Nos demais lugares, o celular tem bandeja de SIM físico além do eSIM. A Openline funciona nos dois casos.","exp.cnOnly":"Este aparelho vem com firmware para o mercado doméstico chinês. O suporte a eSIM existe no papel, mas os perfis internacionais muitas vezes não ativam fora da China continental. Se pretende viajar, confirme a ativação do eSIM com o vendedor antes de comprar.","exp.jpDomestic":"Celulares de operadoras japonesas (NTT DoCoMo, au, SoftBank, Rakuten) costumam ter as bandas travadas no plano de frequências do Japão. O hardware de eSIM funciona no Japão; no exterior, a ativação depende da sobreposição de bandas com as redes locais.","exp.regionLocked":"A ativação de eSIM deste aparelho é bloqueada por região no nível do firmware. Ele só aceita perfis eSIM de operadoras do país/região onde foi vendido.","exp.krOnly":"Este modelo é vendido apenas na Coreia do Sul e usa as bandas das operadoras KT/SKT/LGU+. O hardware de eSIM está presente, mas a ativação no exterior não é confiável.","exp.foldable":"Este é um aparelho dobrável — o eSIM está presente, mas algumas variantes dobráveis vendidas na China não têm suporte a eSIM internacional. Verifique se o código do modelo corresponde ao SKU global.","exp.hotspot":"Este é um roteador Wi-Fi portátil / MiFi, não um celular. Ele aceita eSIM para compartilhar dados móveis com seus outros aparelhos. A Openline é provisionada da mesma forma que em um celular.","exp.simTrayOnly":"Este aparelho tem modem celular, mas só aceita nano-SIM ou micro-SIM físico — não há chip eSIM. Não é possível instalar a Openline como eSIM aqui; seria necessário um plano com SIM físico.","exp.wifiOnly":"Esta variante é somente Wi-Fi — sem modem celular. Ela não aceita nenhum eSIM. Procure a versão LTE / 5G / Cellular do mesmo modelo.","exp.ereader":"Este é um leitor de e-books com modem celular embarcado de fábrica, vinculado ao plano de dados gratuito do fabricante (Amazon Whispernet, B&N nook etc.). O eSIM/SIM não pode ser provisionado pelo usuário — não é possível trocar por um perfil da Openline.","exp.cellularEsimOnly":"Esta variante tem conectividade celular apenas via eSIM — o aparelho não tem bandeja de SIM físico. A Openline é instalada diretamente pelo código QR.","exp.unverifiedVariant":"Nossos dados associam este código de modelo a mais de uma família de produtos. Isso geralmente significa que Apple/Samsung/Google reutilizou um número interno entre gerações, ou que um SKU regional foi renomeado. A Openline ainda deve funcionar, mas se o código do modelo na caixa não corresponder ao aparelho que você está vendo, confirme com o fabricante antes de comprar.","exp.crossBrand":"Este código de modelo também aparece em um aparelho de outra marca (Vivo/iQOO, Xiaomi/POCO, Nokia/HMD, Nubia/ZTE etc.). Normalmente é uma marca irmã do mesmo grupo — o hardware costuma ser idêntico, às vezes apenas com outra marca —, mas o suporte a eSIM e a certificação de operadoras podem diferir entre as duas marcas. Confira na embalagem original do seu aparelho.","exp.modelUnverified":"Não temos um código de modelo/peça oficial para este aparelho — geralmente porque é um wearable, módulo de telemática veicular, roteador ou acessório cujo SKU não é divulgado publicamente. O suporte a eSIM consta na ficha técnica do fabricante, mas a Openline não consegue associar um código de hardware específico para garantir a compatibilidade. Confirme com o fabricante antes de contar com isso.","exp.ambiguous":"O nome do produto aqui é muito curto (“13”, “F7”, “M6”…) e fácil de confundir com modelos de mesmo número de outras marcas ou gerações. Verifique a marca e o código do modelo no seu aparelho para ter certeza de que este item corresponde ao que você tem.","exp.cnFirmware":"Esta unidade vem com firmware para o mercado doméstico chinês. O hardware de eSIM está presente, mas o firmware chinês costuma bloquear a ativação de perfis de eSIM internacionais. Se pretende usar a Openline fora da China continental, confirme com o vendedor, antes de comprar, que o firmware não tem bloqueio regional.","exp.regionExcluded":"As unidades deste aparelho vendidas nas regiões a seguir vêm sem hardware de eSIM, então só a bandeja de SIM físico funciona: {regions}. Nos demais lugares, o eSIM é compatível e a Openline será ativada normalmente. Se você comprou o seu no exterior ou de um importador paralelo, confira o código do modelo na lista do fabricante.","note.3G free":"3G grátis","note.3G/4G":"3G/4G","note.AU/JP/TW excluded":"Exceto AU/JP/TW","note.Ambiguous name":"Nome ambíguo","note.CDMA":"CDMA","note.CN firmware":"Firmware CN","note.CN/HK excluded":"Exceto CN/HK","note.CN/HK/MO: dual nano-SIM":"CN/HK/MO: dois nano-SIM","note.CN/IN":"CN/IN","note.CN/IN dual-eSIM only":"CN/IN: só dual eSIM","note.CN: dual nano-SIM":"CN: dois nano-SIM","note.CN: local eSIM rules":"CN: regras locais de eSIM","note.Carrier watch plan":"Plano de relógio","note.Cross-brand model code":"Código multimarca","note.E-reader":"E-reader","note.Enterprise rugged":"Corporativo resistente","note.Foldable":"Dobrável","note.GPS only":"Somente GPS","note.GPS/satellite tracker":"Rastreador GPS/satélite","note.Google Fi/US only":"Só Google Fi/EUA","note.HarmonyOS":"HarmonyOS","note.JP domestic band lock":"Bandas travadas (JP)","note.KR only":"Só KR","note.KR/CN":"KR/CN","note.KaiOS feature phone":"Celular básico KaiOS","note.Medical alert":"Alerta médico","note.Mobile hotspot":"Roteador móvel","note.Model code unverified":"Código não verificado","note.Nextel/Boost":"Nextel/Boost","note.No eSIM hardware":"Sem hardware de eSIM","note.No eSIM in most regions":"Sem eSIM na maioria das regiões","note.Not on Verizon/Sprint":"Não na Verizon/Sprint","note.SEA excluded":"Exceto SEA","note.SIM tray only":"Só chip físico","note.Sprint":"Sprint","note.US carrier variant":"Variante de operadora dos EUA","note.US model excluded":"Exceto modelo dos EUA","note.US variant excluded":"Exceto variante dos EUA","note.US/HK excluded":"Exceto US/HK","note.US/JP: eSIM ok":"US/JP: eSIM ok","note.US: eSIM only":"US: só eSIM","note.Unverified variant":"Variante não verificada","note.Vehicle telematics":"Telemática veicular","note.Verizon":"Verizon","note.Verizon US no eSIM":"Verizon EUA sem eSIM","note.Verizon-only 5G":"5G só Verizon","note.Wi-Fi + Cellular only":"Só Wi-Fi + Cellular","note.Wi-Fi + free 4G":"Wi-Fi + 4G grátis","note.Wi-Fi only":"Somente Wi-Fi","note.Wi-Fi only in most regions":"Só Wi-Fi na maioria das regiões","note.Wi-Fi/3G":"Wi-Fi/3G","note.Windows Phone":"Windows Phone","note.deprecated":"obsoleto","note.dual-eSIM in EU":"dual eSIM na UE","note.eSIM only":"Só eSIM","note.eSIM only (no SIM tray)":"Só eSIM (sem bandeja)","note.eSIM only in US/JP/CA/Gulf":"Só eSIM em US/JP/CA/Golfo","note.eSIM only via Google Fi":"eSIM só via Google Fi","note.iDEN":"iDEN","note.sunset":"rede desativada"}};
